-- IT purchase orders: printers. Generated by po_import.py from po-printers-match.csv; safe to read.
-- "fill" rows add the PO price (incl. GST), date and vendor to an existing asset where those are blank,
-- and record the PO on it. "new" rows create the asset (In Store, IT team, finance review pending).
-- Sends NO notifications. Refuses to run twice.
\set ON_ERROR_STOP on
BEGIN;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM audit_events WHERE action = 'PO_IMPORTED' AND changes->>'tag' = 'po-printers') THEN
    RAISE EXCEPTION 'The printers from the purchase orders were already imported.';
  END IF;
END $$;
CREATE TEMP TABLE importer ON COMMIT DROP AS
  SELECT ur.user_id AS id FROM user_roles ur WHERE ur.role_code='SUPER_ADMIN' ORDER BY ur.granted_at LIMIT 1;
CREATE TEMP TABLE po (n int PRIMARY KEY, action text, asset_code text, description text, serial text,
  price numeric, po_date date, vendor text, meta jsonb, remark text, category text, asset_type text, location_code text, asset_id uuid) ON COMMIT DROP;
INSERT INTO po (n, action, asset_code, description, serial, price, po_date, vendor, meta, remark, category, asset_type, location_code) VALUES
  (1, 'new', NULL, 'Canon Printer MF2720DW 5621C016AA', NULL, 22420.0, DATE '2024-07-22', 'Odyssey Computer Services Pvt Ltd', '{"po": "IACPF/Office/001", "line": 1, "unit": 1, "date": "2024-07-22", "vendor": "Odyssey Computer Services Pvt Ltd", "person": "Training Academy", "priceExGst": 19000.0, "priceInclGst": 22420.0, "description": "Canon Printer MF2720DW 5621C016AA"}'::jsonb, 'PO IACPF/Office/001 (2024-07-22) for Training Academy.', 'Office Equipment', 'Printer', 'IAC-HO-GF'),
  (2, 'new', NULL, 'fujitsu sp 1130N', NULL, 22715.0, DATE '2024-10-03', 'Comp Tech Computer & Services', '{"po": "IACPF/Office/006", "line": 1, "unit": 1, "date": "2024-10-03", "vendor": "Comp Tech Computer & Services", "person": "Account", "priceExGst": 19250.0, "priceInclGst": 22715.0, "description": "fujitsu sp 1130N"}'::jsonb, 'PO IACPF/Office/006 (2024-10-03) for Account.', 'Office Equipment', 'Scanner', 'IAC-HO-2F'),
  (3, 'new', NULL, 'Printer', NULL, 20414.0, DATE '2025-09-08', 'Optima Infotech', '{"po": "IACPF/Office/089", "line": 1, "unit": 1, "date": "2025-09-08", "vendor": "Optima Infotech", "person": "Ground Floor", "priceExGst": 17300.0, "priceInclGst": 20414.0, "description": "Printer"}'::jsonb, 'PO IACPF/Office/089 (2025-09-08) for Ground Floor.', 'Office Equipment', 'Printer', 'IAC-HO-GF'),
  (4, 'new', NULL, 'Epson Printer L 14150 Colour Printer', NULL, 37760.0, DATE '2025-11-11', 'Optima Infotech', '{"po": "IACPF/Office/105", "line": 1, "unit": 1, "date": "2025-11-11", "vendor": "Optima Infotech", "person": "3Rd Floor (Shared)", "priceExGst": 32000.0, "priceInclGst": 37760.0, "description": "Epson Printer L 14150 Colour Printer"}'::jsonb, 'PO IACPF/Office/105 (2025-11-11) for 3Rd Floor (Shared).', 'Office Equipment', 'Printer', 'IAC-HO-3F'),
  (5, 'new', NULL, 'Brother HL- B2180DWB Printer', NULL, 15340.0, DATE '2026-02-05', 'Optima Infotech', '{"po": "IACPF/Office/111", "line": 1, "unit": 1, "date": "2026-02-05", "dateNote": "PO says 2025-02-05; taken as 2026-02-05 from the PO order", "vendor": "Optima Infotech", "person": "Site NS Cabin", "priceExGst": 13000.0, "priceInclGst": 15340.0, "description": "Brother HL- B2180DWB Printer"}'::jsonb, 'PO IACPF/Office/111 (2026-02-05) for Site NS Cabin.', 'Office Equipment', 'Printer', 'IAC-SITE'),
  (6, 'new', NULL, 'Brother HL-L2440DW Printer', 'E82911A6N209003', 12980.0, DATE '2026-06-27', 'Optima Infotech', '{"po": "IACPF/Office/119", "line": 1, "unit": 1, "date": "2026-06-27", "vendor": "Optima Infotech", "person": "2nd Floor", "priceExGst": 11000.0, "priceInclGst": 12980.0, "description": "Brother HL-L2440DW Printer"}'::jsonb, 'PO IACPF/Office/119 (2026-06-27) for 2nd Floor.', 'Office Equipment', 'Printer', 'IAC-HO-2F');

UPDATE po SET asset_id = a.id FROM assets a WHERE po.action = 'fill' AND a.asset_code = po.asset_code AND a.removed_at IS NULL;
DO $$ DECLARE r record; BEGIN
  FOR r IN SELECT n, asset_code FROM po WHERE action = 'fill' AND asset_id IS NULL LOOP
    RAISE EXCEPTION 'Row %: asset % is not in the software (or was removed). Fix the CSV and regenerate.', r.n, r.asset_code;
  END LOOP;
END $$;

-- Existing assets: blanks only; the PO is recorded on the asset either way.
UPDATE assets a SET
  purchase_cost = coalesce(a.purchase_cost, po.price),
  purchase_date = coalesce(a.purchase_date, po.po_date),
  supplier = coalesce(nullif(btrim(a.supplier), ''), po.vendor),
  remarks = CASE WHEN coalesce(a.remarks, '') LIKE '%' || (po.meta->>'po') || '%' THEN a.remarks
                 ELSE nullif(concat_ws(' ', nullif(btrim(a.remarks), ''), po.remark), '') END,
  legacy_metadata = coalesce(a.legacy_metadata, '{}'::jsonb) || jsonb_build_object('purchaseOrder', po.meta),
  version = a.version + 1, updated_at = now()
FROM po WHERE po.action = 'fill' AND a.id = po.asset_id;

-- Subcategories this import uses that the software does not have yet (held by a person).
INSERT INTO reference_values(kind, code, label) VALUES ('ASSET_TYPE', 'Charger & Adapter', 'Charger & Adapter') ON CONFLICT (kind, code) DO NOTHING;
INSERT INTO asset_type_policies(asset_type_code, requires_custodian, category_code, owning_team_id, handling_team_id) SELECT 'Charger & Adapter', true, 'IT Hardware', handling_team_id, handling_team_id FROM category_policies WHERE category_code = 'IT Hardware' ON CONFLICT (asset_type_code) DO NOTHING;
-- New assets, numbered from the IT counter.
SELECT pg_advisory_xact_lock(hashtextextended('iac-asset-sequence', 0));
DO $$ DECLARE r record; nxt bigint; prefix text; acode text; tid uuid; aid uuid; BEGIN
  SELECT id INTO tid FROM teams WHERE code = 'IT';
  FOR r IN SELECT * FROM po WHERE action = 'new' ORDER BY n LOOP
    SELECT k.next_value, t.asset_code_prefix INTO nxt, prefix FROM team_asset_counters k JOIN teams t ON t.id = k.team_id
     WHERE k.team_id = tid FOR UPDATE OF k;
    LOOP acode := 'IAC-' || prefix || '-' || lpad(nxt::text, 6, '0');
      EXIT WHEN NOT EXISTS (SELECT 1 FROM assets WHERE asset_code = acode); nxt := nxt + 1; END LOOP;
    UPDATE team_asset_counters SET next_value = nxt + 1 WHERE team_id = tid;
    INSERT INTO assets(asset_code, category, asset_type, description, serial_number, ownership_type, status, condition,
      risk_level, owning_team_id, location_id, purchase_date, purchase_cost, currency, supplier, finance_pending, finance_status,
      remarks, legacy_metadata, created_by)
    VALUES (acode, r.category, r.asset_type, r.description, r.serial, 'Owned', 'In Store', 'Unknown', 'Low', tid,
      (SELECT id FROM locations WHERE code = r.location_code),
      r.po_date, r.price, 'INR', r.vendor, true, 'PENDING', r.remark, jsonb_build_object('purchaseOrder', r.meta),
      (SELECT id FROM importer))
    RETURNING id INTO aid;
    UPDATE po SET asset_id = aid, asset_code = acode WHERE n = r.n;
  END LOOP;
END $$;

INSERT INTO audit_events(actor_id, actor_kind, entity_type, entity_id, action, changes, request_id)
SELECT (SELECT id FROM importer), 'USER', 'asset', po.asset_id,
       CASE WHEN po.action = 'new' THEN 'ASSET_CREATED' ELSE 'ASSET_UPDATED' END,
       jsonb_build_object('source', 'IT purchase orders', 'po', po.meta->>'po', 'assetCode', po.asset_code), gen_random_uuid()
  FROM po;
INSERT INTO audit_events(actor_id, actor_kind, entity_type, entity_id, action, changes, request_id)
SELECT (SELECT id FROM importer), 'USER', 'import', NULL, 'PO_IMPORTED', jsonb_build_object('tag', 'po-printers',
  'filled', (SELECT count(*) FROM po WHERE action = 'fill'), 'created', (SELECT count(*) FROM po WHERE action = 'new')), gen_random_uuid();
DO $$ DECLARE r record; BEGIN
  RAISE NOTICE 'Filled from POs: %, created: %', (SELECT count(*) FROM po WHERE action = 'fill'), (SELECT count(*) FROM po WHERE action = 'new');
  FOR r IN SELECT n, asset_code, meta->>'po' AS po, meta->>'person' AS person FROM po WHERE action = 'new' ORDER BY n LOOP
    RAISE NOTICE 'New % from % %', r.asset_code, r.po, coalesce('for ' || r.person, '');
  END LOOP;
END $$;
COMMIT;
